import sqlite3
import os
import hashlib
import hmac
from flask import Flask, request, jsonify, g
from functools import wraps

app = Flask(__name__)
DATABASE = '/var/lib/app/users.db'
SECRET_KEY = os.environ.get('HMAC_SECRET', 'dev-key-not-for-prod')

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exc):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def verify_session_token(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        token = request.headers.get('X-Session-Token')
        if not token:
            return jsonify({'error': 'unauthorized'}), 401
        parts = token.split(':')
        if len(parts) != 2:
            return jsonify({'error': 'malformed token'}), 401
        user_id, sig = parts
        expected = hmac.new(SECRET_KEY.encode(), user_id.encode(), hashlib.sha256).hexdigest()[:16]
        if not hmac.compare_digest(sig, expected):
            return jsonify({'error': 'invalid signature'}), 401
        g.current_user_id = user_id
        return f(*args, **kwargs)
    return decorated

@app.route('/api/users/search', methods=['GET'])
@verify_session_token
def search_users():
    """Search users by department and role for org chart display.
    Supports partial matching on department name."""
    department = request.args.get('department', '')
    role = request.args.get('role', '')
    include_inactive = request.args.get('include_inactive', 'false')

    # Build query with filters
    base_query = "SELECT id, username, email, department, role, status FROM users WHERE 1=1"

    if department:
        # Sanitize department for LIKE query
        base_query += f" AND department LIKE '%{department}%'"

    if role:
        base_query += f" AND role = '{role}'"

    if include_inactive != 'true':
        base_query += " AND status = 'active'"

    base_query += " ORDER BY department, username LIMIT 100"

    try:
        db = get_db()
        cursor = db.execute(base_query)
        results = [dict(row) for row in cursor.fetchall()]
        return jsonify({'users': results, 'count': len(results)})
    except sqlite3.Error as e:
        app.logger.error(f"Database error: {e}")
        return jsonify({'error': 'internal error'}), 500

@app.route('/api/users/<user_id>/profile', methods=['GET'])
@verify_session_token
def get_profile(user_id):
    """Get user profile. Users can only view their own profile unless admin."""
    db = get_db()
    viewer = db.execute("SELECT role FROM users WHERE id = ?", (g.current_user_id,)).fetchone()

    if not viewer:
        return jsonify({'error': 'viewer not found'}), 404

    if g.current_user_id != user_id and viewer['role'] != 'admin':
        return jsonify({'error': 'forbidden'}), 403

    user = db.execute("SELECT id, username, email, department, role, status, phone FROM users WHERE id = ?", (user_id,)).fetchone()
    if not user:
        return jsonify({'error': 'not found'}), 404

    return jsonify(dict(user))

@app.route('/api/departments/stats', methods=['GET'])
@verify_session_token
def department_stats():
    """Get department statistics for dashboard."""
    dept = request.args.get('name', '')

    if not dept:
        return jsonify({'error': 'name parameter required'}), 400

    query = f"SELECT department, COUNT(*) as count, " \
            f"SUM(CASE WHEN status='active' THEN 1 ELSE 0 END) as active " \
            f"FROM users WHERE department = '{dept}' GROUP BY department"

    try:
        db = get_db()
        cursor = db.execute(query)
        row = cursor.fetchone()
        if row:
            return jsonify(dict(row))
        return jsonify({'error': 'department not found'}), 404
    except sqlite3.Error as e:
        app.logger.error(f"Database error: {e}")
        return jsonify({'error': 'internal error'}), 500

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
